import type { HassState } from "../types.js";
import { domainOf } from "../types.js";

export interface CodegenOptions {
  /** Source label for header comment */
  source?: string;
  /** Namespace / module name in generated file */
  moduleName?: string;
}

function toSafeLiteral(entityId: string): string {
  return JSON.stringify(entityId);
}

function groupByDomain(states: HassState[]): Map<string, HassState[]> {
  const map = new Map<string, HassState[]>();
  for (const s of states) {
    const d = domainOf(s.entity_id);
    const list = map.get(d) ?? [];
    list.push(s);
    map.set(d, list);
  }
  for (const [, list] of map) {
    list.sort((a, b) => a.entity_id.localeCompare(b.entity_id));
  }
  return map;
}

function domainConst(domain: string): string {
  // light -> LIGHT_ENTITY_IDS
  return `${domain.toUpperCase().replace(/[^A-Z0-9]/g, "_")}_ENTITY_IDS`;
}

function domainEntityType(domain: string): string {
  // light -> LightEntityId
  const parts = domain.split("_").filter(Boolean);
  const pascal = parts
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
  return `${pascal}EntityId`;
}

/**
 * Generate a TypeScript module that types *this* Home Assistant instance's entities.
 * "Prisma for your home" — entity ids become string-literal unions.
 */
export function generateEntityTypes(
  states: HassState[],
  options: CodegenOptions = {},
): string {
  const source = options.source ?? "Home Assistant /api/states";
  const unique = new Map<string, HassState>();
  for (const s of states) unique.set(s.entity_id, s);
  const list = [...unique.values()].sort((a, b) =>
    a.entity_id.localeCompare(b.entity_id),
  );
  const byDomain = groupByDomain(list);

  const lines: string[] = [
    `/**`,
    ` * AUTO-GENERATED by hass-ts codegen — do not edit by hand.`,
    ` * Source: ${source}`,
    ` * Entities: ${list.length}`,
    ` * Generated: ${new Date().toISOString()}`,
    ` */`,
    ``,
    `export const GENERATED_AT = ${JSON.stringify(new Date().toISOString())} as const;`,
    `export const ENTITY_COUNT = ${list.length} as const;`,
    ``,
  ];

  if (list.length === 0) {
    lines.push(`export type EntityId = string;`);
    lines.push(`export const ENTITY_IDS: readonly EntityId[] = [];`);
    lines.push(``);
    lines.push(`export type EntityDomain = string;`);
    return lines.join("\n");
  }

  // Full entity union
  lines.push(`export type EntityId =`);
  for (const s of list) {
    lines.push(`  | ${toSafeLiteral(s.entity_id)}`);
  }
  lines.push(`;`);
  lines.push(``);
  lines.push(`export const ENTITY_IDS = [`);
  for (const s of list) {
    lines.push(`  ${toSafeLiteral(s.entity_id)},`);
  }
  lines.push(`] as const satisfies readonly EntityId[];`);
  lines.push(``);

  // Domain union
  const domains = [...byDomain.keys()].sort();
  lines.push(`export type EntityDomain =`);
  for (const d of domains) {
    lines.push(`  | ${JSON.stringify(d)}`);
  }
  lines.push(`;`);
  lines.push(``);

  // Per-domain unions + friendly name map
  lines.push(`export const FRIENDLY_NAMES: Partial<Record<EntityId, string>> = {`);
  for (const s of list) {
    const name = s.attributes?.friendly_name;
    if (typeof name === "string" && name.length > 0) {
      lines.push(
        `  ${toSafeLiteral(s.entity_id)}: ${JSON.stringify(name)},`,
      );
    }
  }
  lines.push(`};`);
  lines.push(``);

  for (const d of domains) {
    const entities = byDomain.get(d)!;
    const typeName = domainEntityType(d);
    const constName = domainConst(d);
    lines.push(`export type ${typeName} =`);
    for (const s of entities) {
      lines.push(`  | ${toSafeLiteral(s.entity_id)}`);
    }
    lines.push(`;`);
    lines.push(``);
    lines.push(`export const ${constName} = [`);
    for (const s of entities) {
      lines.push(`  ${toSafeLiteral(s.entity_id)},`);
    }
    lines.push(`] as const satisfies readonly ${typeName}[];`);
    lines.push(``);
  }

  // domain -> entity ids helper type
  lines.push(`export interface DomainEntityMap {`);
  for (const d of domains) {
    lines.push(`  ${JSON.stringify(d)}: ${domainEntityType(d)};`);
  }
  lines.push(`}`);
  lines.push(``);

  lines.push(`export function isEntityId(value: string): value is EntityId {`);
  lines.push(`  return (ENTITY_IDS as readonly string[]).includes(value);`);
  lines.push(`}`);
  lines.push(``);

  return lines.join("\n");
}

/**
 * Parse states from a JSON array string or already-parsed array.
 */
export function parseStatesJson(input: string | HassState[]): HassState[] {
  if (Array.isArray(input)) return input;
  const parsed = JSON.parse(input) as unknown;
  if (!Array.isArray(parsed)) {
    throw new Error("Expected a JSON array of Home Assistant states");
  }
  return parsed as HassState[];
}
